	/** 
	 * jumpstart the process by instantiating2 Dimension
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		dimensionId = DimensionService.getDimensionInstance()
		.createDimension( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		DimensionService.getDimensionInstance()
				.createDimension( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.dimensionSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Dimension : " + successValue.getDimensionId());
							  if (successValue.getDimensionId().equals(dimensionId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfDimensionList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Dimension test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on dimension consumed")
					);
			subscriber.dimensionSubscribe( dimensionId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Dimension : " + successValue.getDimensionId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfDimensionList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on dimension for dimensionId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Dimension. 
	 */
	protected Dimension read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Dimension" );

		Dimension entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Dimension with primary key" );
		msg.append( dimensionId );
		
		DimensionFetchOneSummary fetchOneSummary = new DimensionFetchOneSummary( dimensionId );

		try {
			entity = DimensionService.getDimensionInstance().getDimension( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Dimension " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Dimension.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Dimension." );

		StringBuilder msg = new StringBuilder( "Failed to update a Dimension : " );        
		Dimension entity = read();
		UpdateDimensionCommand command = generateUpdateCommand();
		command.setDimensionId(entity.getDimensionId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Dimension." );

			// for use later on...
			dimensionId = entity.getDimensionId();

			DimensionService proxy = DimensionService.getDimensionInstance();  

			proxy.updateDimension( command ).get();

			LOGGER.info( "-- Successfully saved Dimension - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + dimensionId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Dimension.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Dimension." );

		Dimension entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Dimension with id " + dimensionId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Dimension with id " + dimensionId );

			throw e;
		}

		try{
			DimensionService.getDimensionInstance().delete( new DeleteDimensionCommand( entity.getDimensionId() ) ).get();
			LOGGER.info( "-- Successfully deleted Dimension with id " + dimensionId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Dimension with id " + dimensionId );

			throw e;
		}
	}

	/**
	 * get all Dimensions.
	 */
	protected List<Dimension> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Dimensions:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Dimension : " );        
		List<Dimension> collection  = new ArrayList<>();

		try {
			// call the static get method on the DimensionService
			collection = DimensionService.getDimensionInstance().getAllDimension();
			assertNotNull( collection, "An Empty collection of Dimension was incorrectly returned.");
			
			// Now print out the values
			Dimension entity = null;            
			Iterator<Dimension> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getDimensionId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

